def dinuc_shuffle(s, rng):
    d=Counter(zip(s, s[1:]))
    # build multigraph, find Eulerian path
    edges=defaultdict(list)
    for (a,b),c in d.items():
        edges[a].extend([b]*c)
    start=s[0]
    stack=[start]; path=[]
    # Hierholzer
