import random, statistics
from collections import Counter, defaultdict
seq = ''.join(l.strip() for l in open('region.fasta') if not l.startswith('>'))
n=len(seq)
def dinuc_shuffle(s, rng):
    ed=defaultdict(list)
    for a,b in zip(s,s[1:]): ed[a].append(b)
    for k in ed: rng.shuffle(ed[k])
    stack=[s[0]]; out=[]
    while stack:
        v=stack[-1]
        if ed.get(v): stack.append(ed[v].pop())
        else: out.append(stack.pop())
    return ''.join(out[::-1])
comp={'A':'T','T':'A','C':'G','G':'C'}
def rcf(x): return ''.join(comp[c] for c in reversed(x))
starts=('ATG','GTG','TTG','ATT','CTG'); stops=('TAA','TAG','TGA')
def orfs(s, minaa):
    out=[]
    for strand,ss in (('+',s),('-',rcf(s))):
        for f in range(3):
            i=f
            while i<len(ss)-2:
                if ss[i:i+3] in starts:
                    j=i
                    while j<len(ss)-2 and ss[j:j+3] not in stops: j+=3
                    if (j-i)//3>=minaa: out.append(((j-i)//3, strand, f))
                    i=j
                else: i+=3
    return out
